#include <atomic>
#include <iostream>
#include <thread>

int main() {
    std::atomic_flag ready{};
    std::jthread worker([&] {
        ready.test_and_set();
        ready.notify_one();
        ready.notify_all();
    });
    ready.wait(false);
    worker.join();
    std::cout << std::boolalpha << ready.test() << "\n";
}
